623	\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
624		\lean{MIPStarRE.QPBT.primeTauShift, MIPStarRE.QPBT.primeTauPhase}
625		\lean{MIPStarRE.QPBT.primeTauObservable, MIPStarRE.QPBT.primePauliFourier}
626		\lean{MIPStarRE.QPBT.primePauliVec, MIPStarRE.QPBT.primePauliProj}
627		\lean{MIPStarRE.QPBT.primePauliVec_orthonormal}
628		\lean{MIPStarRE.QPBT.primeTauObservable_mulVec_primePauliVec}
629		\lean{MIPStarRE.QPBT.primePauliProj_mul_primePauliProj}
630		\lean{MIPStarRE.QPBT.primePauliProj_conjTranspose}
631		\lean{MIPStarRE.QPBT.posSemidef_primePauliProj}
632		\lean{MIPStarRE.QPBT.primePauliProj_isProj, MIPStarRE.QPBT.sum_primePauliProj_eq_one}
633		\leanok
634		\uses{def:subfield-trace, def:lin-reg}
635		Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
636		observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
637		\begin{equation}\label{eq:pauli-fp}
638			\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
639			\qquad \text{and} \qquad
640			\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
641		\end{equation}
642		for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
643		\emph{generalized Pauli observables over $\F_q$} are the unitaries on
644		$\C^{\F_q}$
645		\[
646			\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
647			\qquad \text{and} \qquad
648			\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
649		\]
650		for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
651		(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
652		the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
653		signs. All the $\tau^X$ operators commute with one another, as do all the
654		$\tau^Z$ operators. Their common eigenbases consist of the vectors
655		$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
656		\[
657			\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
658			\omega^{-\tr(ej)} \ket{j}\;, \qquad
659			\ket{e_Z} = \ket{e}\;;
660		\]
661		the Fourier transform
662		\begin{equation}\label{eq:fourier-f}
663			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
664			\omega^{-\tr(ab)} \ket{a}\bra{b}
665		\end{equation}
666		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
667		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
668		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
669		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
670		\[
671			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
672			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
673		\]
674		for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
675		The distinction between the general prime-characteristic definitions and
676		the characteristic-two specializations used by the Pauli basis test is
677		documented in \cite{gap:qpbt_characteristic-two-pauli-scope}.
678	\end{definition}
